MorphButton.source:
import type { Meta, StoryObj } from "@storybook/react-vite";
import { useState } from "react";
import { useArgs } from "storybook/preview-api";
import { fn } from "storybook/test";
import { Field } from "../inputs/Field";
import { Input } from "../inputs/Input";
import { MorphButton, type MorphButtonProps } from "./MorphButton";
import { MorphButtonExample } from "../../../docs/examples/MorphButtonExample";
import exampleSource from "../../../docs/examples/MorphButtonExample.tsx?raw";

const meta = {
  title: "Actions/MorphButton",
  id: "components-morphbutton",
  component: MorphButton,
  tags: ["!autodocs"],
  args: { status: "idle", onClick: fn() },
} satisfies Meta<typeof MorphButton>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Click to run a fake request: loading for 1.2 s, done for 1.5 s, then back to idle. */
export const Default: Story = {
  render: function Render(args) {
    const [, updateArgs] = useArgs();

    function onClick(event: React.MouseEvent<HTMLButtonElement>) {
      args.onClick?.(event);
      updateArgs({ status: "loading" });
      setTimeout(() => updateArgs({ status: "success" }), 1200);
      setTimeout(() => updateArgs({ status: "idle" }), 2700);
    }

    return <MorphButton {...args} onClick={onClick} />;
  },
};

function MorphForm({ onStatusChange, ...args }: MorphButtonProps & { onStatusChange: (status: MorphButtonProps["status"]) => void }) {
  const [name, setName] = useState("");
  const [data, setData] = useState("");
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        setData(JSON.stringify(Object.fromEntries(new FormData(event.currentTarget, event.submitter))));
        onStatusChange("loading");
        setTimeout(() => onStatusChange("success"), 1200);
        setTimeout(() => onStatusChange("idle"), 2700);
      }}
      className="grid w-80 max-w-full gap-3"
    >
      <Field label="Display name">
        <Input name="name" value={name} onValueChange={setName} />
      </Field>
      <MorphButton {...args} type="submit" name="intent" value="save" className="justify-self-start">
        <span>Save</span>
      </MorphButton>
      <output className="min-h-5 text-label text-muted">{data}</output>
    </form>
  );
}

/** Submit by clicking Save or pressing Enter in the field; the button loads, succeeds, then returns to idle. */
export const InAForm: Story = {
  name: "In a form",
  render: function Render(args) {
    const [, updateArgs] = useArgs();
    return <MorphForm {...args} onStatusChange={(status) => updateArgs({ status })} />;
  },
};

/** Disabled while idle: pointer and keyboard presses do not start the request. */
export const Disabled: Story = { args: { disabled: true } };

export const Usage: Story = {
  render: () => <MorphButtonExample />,
  parameters: { docs: { source: { code: exampleSource, language: "tsx" } } },
};

SelectionBar.source:
import type { Meta, StoryObj } from "@storybook/react-vite";
import { useState } from "react";
import { fn } from "storybook/test";
import { StatusBadge } from "../feedback/StatusBadge";
import { Checkbox } from "../inputs/Checkbox";
import { Card } from "../layout/Card";
import { Button } from "./Button";
import { SelectionBar, type SelectionBarProps } from "./SelectionBar";

const tasks = [
  { id: "quote", title: "Send the revised quote to Studio Bernasconi", done: false },
  { id: "room", title: "Book a room for Thursday's design review", done: true },
  { id: "dashboard", title: "Reply to Helvetia Analytics about the dashboard timeline", done: false },
  { id: "audit", title: "Go through the accessibility audit of the customer portal and file an issue for each finding", done: false },
  { id: "certificate", title: "Renew the certificate for the staging domain", done: false },
  { id: "onboarding", title: "Update the onboarding checklist", done: true },
  { id: "invoices", title: "Export the October invoices for accounting", done: false },
  { id: "laptops", title: "Order laptops for the new interns", done: false },
  { id: "slides", title: "Prepare slides for the quarterly all-hands", done: false },
  { id: "archive", title: "Archive last year's project folders", done: false },
];

function TaskList(props: SelectionBarProps) {
  const [rows, setRows] = useState(tasks);
  const [selection, setSelection] = useState<string[]>([]);

  return (
    <>
      <Card className="w-xl max-w-[calc(100vw-2rem)] px-4 py-2">
        <ul role="list" className="divide-y divide-line">
          {rows.map((task) => (
            <li key={task.id} className="flex items-center justify-between gap-3 py-1">
              <Checkbox
                label={task.title}
                checked={selection.includes(task.id)}
                onCheckedChange={(checked) =>
                  setSelection(checked ? [...selection, task.id] : selection.filter((id) => id !== task.id))
                }
              />
              <StatusBadge status={task.done ? "success" : "neutral"} label={task.done ? "Done" : "To do"} className="shrink-0" />
            </li>
          ))}
        </ul>
      </Card>
      <SelectionBar
        {...props}
        count={selection.length}
        onClear={() => {
          setSelection([]);
          props.onClear();
        }}
        className="fixed inset-x-0 bottom-6 mx-auto w-fit"
      >
        <Button
          variant="ghost"
          size="sm"
          onClick={() => setRows(rows.map((task) => (selection.includes(task.id) ? { ...task, done: true } : task)))}
        >
          Mark as done
        </Button>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => {
            setRows(rows.filter((task) => !selection.includes(task.id)));
            setSelection([]);
          }}
        >
          Delete
        </Button>
      </SelectionBar>
    </>
  );
}

const meta = {
  title: "Actions/SelectionBar",
  id: "components-selectionbar",
  component: SelectionBar,
  args: { count: 0, onClear: fn(), children: null },
} satisfies Meta<typeof SelectionBar>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Check tasks to raise the bar, all ten to see it widen as the count rolls; Tab to its actions and press Enter or Space; × or Delete empties the selection and the bar sinks away. */
export const Default: Story = {
  render: function Render(args) {
    return <TaskList {...args} />;
  },
};

SwipeButton.source:
import type { Meta, StoryObj } from "@storybook/react-vite";
import { useState } from "react";
import { useArgs } from "storybook/preview-api";
import { fn } from "storybook/test";
import { SwipeButton, type SwipeButtonProps } from "./SwipeButton";

function StatefulSwipeButton({
  onConfirmedChange,
  ...props
}: SwipeButtonProps & { onConfirmedChange: (confirmed: boolean) => void }) {
  const [confirmed, setConfirmed] = useState(props.confirmed);
  return (
    <SwipeButton
      {...props}
      confirmed={confirmed}
      onConfirm={() => {
        props.onConfirm();
        setConfirmed(true);
        onConfirmedChange(true);
        setTimeout(() => {
          setConfirmed(false);
          onConfirmedChange(false);
        }, 1500);
      }}
    />
  );
}

const meta = {
  title: "Actions/SwipeButton",
  id: "components-swipebutton",
  component: SwipeButton,
  args: { confirmed: false, onConfirm: fn() },
} satisfies Meta<typeof SwipeButton>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Drag the knob to the end, or focus the button and press Enter or Space, to confirm; let go early and it springs home. The done state resets after 1.5 s. */
export const Default: Story = {
  render: function Render(args) {
    const [, updateArgs] = useArgs();
    return (
      <div className="w-70 max-w-full">
        <StatefulSwipeButton {...args} onConfirmedChange={(confirmed) => updateArgs({ confirmed })} />
      </div>
    );
  },
};

