}

function SliderForm(props: SliderProps) {
  const [value, setValue] = useState(props.value);
  const [data, setData] = useState("");
  return (
    <form
      className="w-80 max-w-full space-y-4"
      onSubmit={(event) => {
        event.preventDefault();
