import type { Meta, StoryObj } from "@storybook/react-vite";
import { useEffect, useState } from "react";
import { useArgs } from "storybook/preview-api";
import { Button } from "../actions/Button";
import { Toast } from "./Toast";

const meta = {
  title: "Feedback/Toast",
  id: "components-toast",
  component: Toast,
  args: { status: "success" },
} satisfies Meta<typeof Toast>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Click Next, or press Enter or Space, to swap between sharing and success; the pill follows its content. */
export const Default: Story = {
  render: function Render(args) {
    const [, updateArgs] = useArgs();
    return (
      <div className="flex flex-col items-center gap-4">
        <Toast {...args} />
        <Button
          variant="secondary"
          size="sm"
          onClick={() => updateArgs(args.status === "success" ? { status: "loading", children: "Sharing…" } : { status: "success", children: "Link copied" })}
        >
          Next
        </Button>
      </div>
    );
  },
};

/** Loading and success take turns every 1.2 s, like a toast that follows a request. */
export const Sharing: Story = {
  render: function Render() {
    const [status, setStatus] = useState<"loading" | "success">("loading");

    useEffect(() => {
      const id = setInterval(() => setStatus((s) => (s === "loading" ? "success" : "loading")), 1200);
      return () => clearInterval(id);
    }, []);

    return <Toast status={status}>{status === "loading" ? "Sharing…" : "Link copied"}</Toast>;
  },
};

ToastStack.source:
import type { Meta, StoryObj } from "@storybook/react-vite";
import { useRef, useState } from "react";
import { fn } from "storybook/test";
import { Button } from "../actions/Button";
import { Icon } from "../data-display/Icon";
import { ToastStack, type ToastStackProps } from "./ToastStack";

function Done() {
  return (
    <Icon size={16}>
      <circle cx="12" cy="12" r="12" className="fill-accent stroke-none" />
      <path d="M7.125 12.375 10.5 15.75l6.375-6.75" className="stroke-on-accent" />
    </Icon>
  );
}

const messages = ["Photo uploaded", "Reminder set", "Playlist shared", "Draft saved", "Password changed"];

function StatefulToastStack(props: ToastStackProps) {
  const [toasts, setToasts] = useState(props.toasts);
  const count = useRef(props.toasts.length);

  function remove(id: string) {
    setToasts((toasts) => toasts.filter((toast) => toast.id !== id));
  }

  function add() {
    count.current += 1;
    const toast = { id: String(count.current), label: messages[count.current % messages.length], icon: <Done /> };
    setToasts((toasts) => [...toasts, toast]);
    setTimeout(() => remove(toast.id), 4000);
  }

  return (
    <div className="flex w-80 max-w-full flex-col items-center gap-8">
      <ToastStack
        {...props}
        toasts={toasts}
        onDismiss={(id) => {
          remove(id);
          props.onDismiss(id);
        }}
      />
      <Button variant="secondary" onClick={add}>
        Show a toast
      </Button>
    </div>
  );
}

const meta = {
  title: "Feedback/ToastStack",
  id: "components-toaststack",
  component: ToastStack,
  args: {
    toasts: [
      { id: "1", label: "Invite sent", icon: <Done /> },
      { id: "2", label: "Changes saved", icon: <Done /> },
      { id: "3", label: "Link copied", icon: <Done /> },
    ],
    onDismiss: fn(),
  },
} satisfies Meta<typeof ToastStack>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Hover the stack or Tab into it to fan it out; × (or Enter on it) dismisses a toast; Show a toast adds one that leaves after 4 s. */
export const Default: Story = {
  render: function Render(args) {
    return <StatefulToastStack {...args} />;
  },
};

