import type { Meta, StoryObj } from "@storybook/react-vite";
import { useState } from "react";
import { fn } from "storybook/test";
import { Button } from "../actions/Button";
import { Card } from "../layout/Card";
import { Icon } from "./Icon";
import { Tag } from "./Tag";

const meta = {
  title: "Data display/Tag",
  id: "components-tag",
  component: Tag,
  args: { label: "Customer research" },
  render: (args) => (
    <Card className="p-6">
      <Tag {...args} />
    </Card>
  ),
} satisfies Meta<typeof Tag>;

export default meta;
type Story = StoryObj<typeof meta>;

/** A static tag on a paper card; edit the label in Controls. */
export const Default: Story = {};

/** Remove the tag by click, Enter or Space, then restore it to try again. */
export const Removable: Story = {
  args: {
    label: "Zurich office",
    icon: (
      <Icon size={14}>
        <path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0" />
        <circle cx="12" cy="10" r="3" />
      </Icon>
    ),
    onRemove: fn(),
  },
  render: function Render(args) {
    const [removed, setRemoved] = useState(false);
    return (
      <Card className="p-6">
        {removed ? (
          <Button size="sm" onClick={() => setRemoved(false)}>Restore tag</Button>
        ) : (
          <Tag {...args} onRemove={() => {
            args.onRemove!();
            setRemoved(true);
          }} />
        )}
      </Card>
    );
  },
};

