import type { Meta, StoryObj } from "@storybook/react-vite";
import { useArgs } from "storybook/preview-api";
import { fn } from "storybook/test";
import { Button } from "../actions/Button";
import { Icon } from "../data-display/Icon";
import { Separator } from "../layout/Separator";
import { BottomSheet } from "./BottomSheet";

const actions = [
  { label: "Add to queue", paths: ["M11 12H3", "M16 6H3", "M16 18H3", "M18 9v6", "M21 12h-6"] },
  { label: "Go to artist", paths: ["M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2", "M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0"] },
  { label: "Share", paths: ["M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8", "m16 6-4-4-4 4", "M12 2v13"] },
  { label: "Download", paths: ["M12 15V3", "M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4", "m7 10 5 5 5-5"] },
];

const meta = {
  title: "Overlays/BottomSheet",
  id: "components-bottomsheet",
  component: BottomSheet,
  parameters: { layout: "fullscreen" },
  args: {
    open: false,
    onOpenChange: fn(),
    children: (
      <div className="px-2 pb-6">
        <div className="px-3 pb-3">
          <p className="text-body font-semibold text-ink">Winter Breeze</p>
          <p className="text-label text-muted">Arulo</p>
        </div>
        <Separator className="mx-3 mb-2" />
        {actions.map(({ label, paths }) => (
          <Button key={label} variant="ghost" className="w-full">
            <span className="flex w-full items-center gap-3">
              <Icon size={20} className="text-muted">{paths.map((d) => <path key={d} d={d} />)}</Icon>
              {label}
            </span>
          </Button>
        ))}
      </div>
    ),
  },
  render: function Render(args) {
    const [, updateArgs] = useArgs();
    return (
      <div className="grid min-h-screen place-items-center">
        <Button aria-haspopup="dialog" aria-expanded={args.open} onClick={() => updateArgs({ open: true })}>Open sheet</Button>
        <BottomSheet {...args} onOpenChange={(open) => { args.onOpenChange(open); updateArgs({ open }); }} />
      </div>
    );
  },
} satisfies Meta<typeof BottomSheet>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Open the sheet, then drag its grab strip down (a flick or past halfway closes it, a short drag springs back), tap the handle, click the backdrop or press Escape. */
export const Default: Story = {};

export const LongContent: Story = {
  args: {
    children: (
      <div className="p-5">
        <h2 className="mb-4 text-body font-semibold">Your library</h2>
        <ul role="list">
          {Array.from({ length: 24 }, (_, i) => (
            <li key={i}><Button variant="ghost" className="w-full"><span className="w-full text-left">Track {i + 1}</span></Button></li>
          ))}
        </ul>
      </div>
    ),
  },
};

ContextMenu.source:
import type { Meta, StoryObj } from "@storybook/react-vite";
import { useState } from "react";
import { fn } from "storybook/test";
import { ContextMenu } from "./ContextMenu";
import { Dialog } from "./Dialog";
import { Button } from "../actions/Button";
import { Card } from "../layout/Card";
import { Icon } from "../data-display/Icon";

const meta = {
  title: "Overlays/ContextMenu",
  id: "components-contextmenu",
  component: ContextMenu,
  args: {
    actions: [
      { label: "Rename", icon: <Icon><path d="m16 3 5 5-12 12H4v-5zM14 5l5 5" /></Icon> },
      { label: "Download", disabled: true },
      { label: "Share" },
      { label: "Move to archive" },
    ],
    onAction: fn(),
    children: <Card className="p-6"><p className="font-medium">Project notes</p><p className="mt-2 text-sm text-muted">Right-click, hold on touch, or use Shift+F10.</p></Card>,
  },
} satisfies Meta<typeof ContextMenu>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Right-click the card, hold it on touch, or focus it and press Shift+F10 or the context-menu key; arrows move, Enter or Space runs, Escape or a press outside closes. */
export const Default: Story = {
  render: function Render(args) {
    const [action, setAction] = useState("");
    const [clicks, setClicks] = useState(0);
    return (
      <div className="grid w-80 max-w-full gap-4">
        <ContextMenu {...args} onAction={(action) => { args.onAction(action); setAction(action.label); }}>
          <Card className="grid gap-4 p-6"><p className="font-medium">Project notes</p><Button variant="secondary" onClick={() => setClicks(clicks + 1)}>Open document</Button></Card>
        </ContextMenu>
        <Button variant="secondary">Outside action</Button>
        <output data-result="action" className="text-label">{action}</output>
        <output data-result="clicks" className="text-label">{clicks}</output>
      </div>
    );
  },
};

export const LongListAtTheEdge: Story = {
  args: { actions: Array.from({ length: 30 }, (_, i) => ({ label: `Action ${String(i + 1).padStart(2, "0")} — project document` })) },
  decorators: [(Story) => <div className="flex h-[calc(100vh-4rem)] w-[calc(100vw-4rem)] items-end justify-end"><Story /></div>],
};

export const InsideAClippingCard: Story = {
  args: { children: <p className="p-4">Notes inside a clipped card</p> },
  decorators: [(Story) => <Card className="w-80 max-w-full overflow-hidden p-4"><Story /></Card>],
};

export const InsideADialog: Story = {
  render: function Render(args) {
    const [open, setOpen] = useState(false);
    const [action, setAction] = useState("");
    return (
      <Dialog open={open} onOpenChange={setOpen} title="Project document">
        <div className="mt-4 grid gap-4">
          <ContextMenu {...args} onAction={(action) => { args.onAction(action); setAction(action.label); }} />
          <output className="text-label">{action}</output>
        </div>
      </Dialog>
    );
  },
};

Dialog.source:
import type { Meta, StoryObj } from "@storybook/react-vite";
import { useState } from "react";
import { fn } from "storybook/test";
import { Button } from "../actions/Button";
import { Field } from "../inputs/Field";
import { Input } from "../inputs/Input";
import { Dialog } from "./Dialog";

const meta = {
  title: "Overlays/Dialog",
  id: "components-dialog",
  component: Dialog,
  parameters: { layout: "padded" },
  args: {
    open: false,
    onOpenChange: fn(),
    children: <InviteContent />,
  },
} satisfies Meta<typeof Dialog>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Click Open dialog: the button grows into the dialog; Escape, the close button or the backdrop close it and focus returns to the button. */
export const Default: Story = {
  render: function Render(args) {
    const [open, setOpen] = useState(args.open);
    return <div className="flex gap-2"><Dialog {...args} open={open} onOpenChange={(next) => { args.onOpenChange(next); setOpen(next); }} /><Button variant="ghost">Next</Button></div>;
  },
};

export const LongContent: Story = {
  args: {
    title: "Playlist permissions",
    children: <Permissions />,
  },
  render: Default.render,
};

export const WithoutTrigger: Story = {
  args: { trigger: null },
  render: function Render(args) {
    const [open, setOpen] = useState(args.open);
    return <><Button onClick={() => setOpen(true)}>Open from elsewhere</Button><Dialog {...args} open={open} onOpenChange={setOpen} /></>;
  },
};

function InviteContent() {
  const [email, setEmail] = useState("");
  return <><p className="mt-1 text-sm text-muted">Invite people to edit this playlist. They get an email with a link to it.</p><div className="mt-4 flex gap-2"><Input type="email" value={email} onValueChange={setEmail} aria-label="Email" placeholder="name@example.com" className="min-w-0 grow" /><Button>Invite</Button></div></>;
}

function Permissions() {
  const [message, setMessage] = useState("");
  return <div className="space-y-4 pt-4">{Array.from({ length: 16 }, (_, index) => <p key={index} className="text-sm text-muted">Collaborator {index + 1} can add songs and edit this playlist. Changes are visible to everyone with access.</p>)}<Field label="Message"><Input value={message} onValueChange={setMessage} placeholder="Add a note" /></Field><Button>Save permissions</Button></div>;
}

Drawer.source:
import type { Meta, StoryObj } from "@storybook/react-vite";
import { useArgs } from "storybook/preview-api";
import { fn } from "storybook/test";
import { Button } from "../actions/Button";
import { Drawer } from "./Drawer";

const meta = {
  title: "Overlays/Drawer",
  id: "components-drawer",
  component: Drawer,
  parameters: { layout: "fullscreen" },
  args: {
    open: false,
    onOpenChange: fn(),
    title: "Project details",
    children: (
      <div className="space-y-3 text-body">
        <p>Keep notes, files and conversations together in one workspace.</p>
        <p className="text-muted">Only people invited to this project can view these details.</p>
      </div>
    ),
  },
  render: function Render(args) {
    const [, updateArgs] = useArgs();
    function onOpenChange(open: boolean) {
      args.onOpenChange(open);
      updateArgs({ open });
    }
    return (
      <div className="grid min-h-screen place-items-center">
        <Button aria-haspopup="dialog" aria-expanded={args.open} onClick={() => onOpenChange(true)}>Open drawer</Button>
        <Drawer {...args} onOpenChange={onOpenChange}>
          <div className="space-y-5 px-5 pb-5">
            {args.children}
            <Button onClick={() => onOpenChange(false)}>Done</Button>
          </div>
        </Drawer>
      </div>
    );
  },
} satisfies Meta<typeof Drawer>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Open the drawer, then drag its header toward the edge, press Close or Escape, or click the backdrop; focus returns to the button. */
export const Default: Story = {};

export const Left: Story = {
  args: { side: "left" },
};

export const LongContent: Story = {
  args: {
    title: "Project activity",
    children: (
      <ol role="list" className="space-y-5">
        {Array.from({ length: 20 }, (_, i) => (
          <li key={i} className="text-body">
            <p className="font-medium">Draft {i + 1} reviewed</p>
            <p className="text-muted">The latest changes are ready for the next review.</p>
          </li>
        ))}
      </ol>
    ),
  },
};

Island.source:
import type { Meta, StoryObj } from "@storybook/react-vite";
import { useArgs } from "storybook/preview-api";
import { fn } from "storybook/test";
import { Button } from "../actions/Button";
import { IconButton } from "../actions/IconButton";
import { Icon } from "../data-display/Icon";
import { Island } from "./Island";


const timer = ["M10 2h4", "m12 14 3-3", "M20 14a8 8 0 1 1-16 0 8 8 0 0 1 16 0"];
const pause = [
  "M6 5a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1H7a1 1 0 0 1-1-1Z",
  "M14 5a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1h-2a1 1 0 0 1-1-1Z",
];
const close = ["M18 6 6 18", "m6 6 12 12"];
const mic = ["M12 19v3", "M19 10v2a7 7 0 0 1-14 0v-2", "M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0Z"];
const phone = [
  "M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92Z",
];
const download = ["M12 15V3", "M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4", "m7 10 5 5 5-5"];

const activities = [
  {
    activity: "Timer",
    leading: (
      <span className="grid size-6 place-items-center text-accent">
        <Icon size={16}>{timer.map((d) => <path key={d} d={d} />)}</Icon>
      </span>
    ),
    trailing: <span className="px-1 text-accent tabular-nums">4:59</span>,
    children: (
      <div className="flex h-full items-center gap-2 p-5">
        <IconButton label="Pause" className="shrink-0 [--color-ink:var(--color-accent)] [--color-paper:var(--color-on-accent)]">
          <Icon size={20}>{pause.map((d) => <path key={d} d={d} />)}</Icon>
        </IconButton>
        <IconButton label="Cancel" className="shrink-0 [--color-ink:var(--color-ink-3)]">
          <Icon size={20}>{close.map((d) => <path key={d} d={d} />)}</Icon>
        </IconButton>
        <div className="ml-auto text-right">
          <p className="text-label leading-4 text-paper/55">Timer</p>
          <p className="text-3xl leading-7 font-semibold text-accent tabular-nums">4:59</p>
        </div>
      </div>
    ),
  },
  {
    activity: "Call",
    leading: (
      <span className="flex items-center gap-2">
        <span className="grid size-6 place-items-center rounded-full bg-ink-3 text-caption font-semibold">MC</span>
        Maya
      </span>
    ),
    trailing: <span className="px-1 text-accent tabular-nums">0:42</span>,
    children: (
      <div className="flex h-full items-center gap-3 p-5">
        <span className="grid size-11 shrink-0 place-items-center rounded-full bg-ink-3 text-body font-semibold">MC</span>
        <div className="min-w-0 grow">
          <p className="truncate text-body font-semibold">Maya Chen</p>
          <p className="text-label text-accent tabular-nums">0:42</p>
        </div>
        <div className="flex gap-2">
          <IconButton label="Mute" className="shrink-0 [--color-ink:var(--color-ink-3)]">
            <Icon size={20}>{mic.map((d) => <path key={d} d={d} />)}</Icon>
          </IconButton>
          <IconButton label="End call" variant="secondary" className="shrink-0">
            <span className="rotate-135">
              <Icon size={20}>{phone.map((d) => <path key={d} d={d} />)}</Icon>
            </span>
          </IconButton>
        </div>
      </div>
    ),
  },
  {
    activity: "Download",
    leading: (
      <span className="grid size-6 place-items-center">
        <Icon size={16}>{download.map((d) => <path key={d} d={d} />)}</Icon>
      </span>
    ),
    trailing: (
      <svg viewBox="0 0 24 24" className="size-6 -rotate-90 fill-none" strokeWidth={1.5} strokeLinecap="round">
        <circle cx="12" cy="12" r="8" className="stroke-ink-3" />
        <circle cx="12" cy="12" r="8" pathLength={1} strokeDasharray="0.4 1" className="stroke-accent" />
      </svg>
    ),
    children: (
      <div className="flex h-full items-center gap-3 p-5">
        <span className="grid size-11 shrink-0 place-items-center rounded-full bg-ink-3">
          <Icon size={20}>{download.map((d) => <path key={d} d={d} />)}</Icon>
        </span>
        <div className="min-w-0 grow">
          <p className="truncate text-body font-semibold">Report.pdf</p>
          <p className="text-label text-paper/55 tabular-nums">18.4 of 46 MB</p>
        </div>
        <IconButton label="Cancel download" className="relative shrink-0 [--color-ink:var(--color-ink-3)]">
          <svg viewBox="0 0 44 44" className="absolute inset-0 -rotate-90 fill-none" strokeWidth={1.5} strokeLinecap="round">
            <circle cx="22" cy="22" r="20.5" pathLength={1} strokeDasharray="0.4 1" className="stroke-accent" />
          </svg>
          <Icon size={16}>{close.map((d) => <path key={d} d={d} />)}</Icon>
        </IconButton>
      </div>
    ),
  },
];

const meta = {
  title: "Overlays/Island",
  id: "components-island",
  component: Island,
  args: { ...activities[0], expanded: false, onExpandedChange: fn() },
} satisfies Meta<typeof Island>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Click the island, or Tab to it and press Enter, to expand it; press Escape or click outside to fold it. Next activity steps through a timer, a call and a download. */
export const Default: Story = {
  render: function Render(args) {
    const [, updateArgs] = useArgs();
    const index = activities.findIndex(({ activity }) => activity === args.activity);
    return (
      <div className="flex flex-col items-center gap-12">
        <Island
          {...args}
          {...activities[index]}
          onExpandedChange={(expanded) => {
            args.onExpandedChange(expanded);
            updateArgs({ expanded });
          }}
        />
        <Button size="sm" variant="secondary" onPointerDown={(event) => event.stopPropagation()} onClick={() => updateArgs({ activity: activities[(index + 1) % activities.length].activity, expanded: false })}>Next activity</Button>
      </div>
    );
  },
};

Popover.source:
import type { Meta, StoryObj } from "@storybook/react-vite";
import { useState } from "react";
import { useArgs } from "storybook/preview-api";
import { fn } from "storybook/test";
import { Button } from "../actions/Button";
import { Card } from "../layout/Card";
import { Popover } from "./Popover";
import { Dialog } from "./Dialog";

const meta = {
  title: "Overlays/Popover",
  id: "components-popover",
  component: Popover,
  args: {
    open: false,
    onOpenChange: fn(),
    children: (
      <div className="p-4">
        <p className="text-body font-semibold text-ink">Winter Breeze</p>
        <p className="text-label text-muted">Arulo</p>
        <dl className="mt-3 grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 text-label">
          <dt className="text-muted">Album</dt>
          <dd className="text-right">Lumen</dd>
          <dt className="text-muted">Released</dt>
          <dd className="text-right">2024</dd>
          <dt className="text-muted">Length</dt>
          <dd className="text-right tabular-nums">2:20</dd>
        </dl>
        <Button className="mt-4 w-full">Go to album</Button>
      </div>
    ),
  },
} satisfies Meta<typeof Popover>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Click Details, or focus it and press Enter or Space; click outside or press Escape to close it. */
export const Default: Story = {
  render: function Render(args) {
    const [, updateArgs] = useArgs();
    return (
      <Popover
        {...args}
        onOpenChange={(open) => {
          args.onOpenChange(open);
          updateArgs({ open });
        }}
      />
    );
  },
};

const placements = [
  { placement: "bottom-left", label: "Bottom left" },
  { placement: "bottom-center", label: "Bottom center" },
  { placement: "bottom-right", label: "Bottom right" },
  { placement: "top-left", label: "Top left" },
  { placement: "top-center", label: "Top center" },
  { placement: "top-right", label: "Top right" },
] as const;

/** Each popover opens toward its placement, and flips only when the viewport has more room the other way. */
export const Placements: Story = {
  parameters: { layout: "fullscreen" },
  render: function Render(args) {
    const [open, setOpen] = useState<string | null>(null);
    return (
      <div className="grid min-h-dvh grid-cols-3 place-items-center gap-8 p-8">
        {placements.map(({ placement, label }) => (
          <Popover key={placement} {...args} placement={placement} trigger={label} open={open === placement} onOpenChange={(next) => setOpen(next ? placement : null)} />
        ))}
      </div>
    );
  },
};

export const NearTheEdges: Story = {
  parameters: { layout: "fullscreen" },
  render: function Render(args) {
    const [, updateArgs] = useArgs();
    return <div className="fixed right-4 bottom-4"><Popover {...args} trigger="Album details" onOpenChange={(open) => { args.onOpenChange(open); updateArgs({ open }); }} /></div>;
  },
};

export const InsideAClippingCard: Story = {
  render: function Render(args) {
    const [, updateArgs] = useArgs();
    return <Card className="h-20 w-48 overflow-hidden p-4"><Popover {...args} onOpenChange={(open) => { args.onOpenChange(open); updateArgs({ open }); }} /></Card>;
  },
};

export const InsideDialog: Story = {
  render: function Render(args) {
    const [dialog, setDialog] = useState(false);
    const [open, setOpen] = useState(false);
    return <Dialog open={dialog} onOpenChange={setDialog} title="Album"><div className="flex items-center gap-3 py-4"><Popover {...args} open={open} onOpenChange={setOpen} /><Button variant="ghost">Next</Button></div></Dialog>;
  },
};

